cypress_script:
describe('Login Functionality', () => {
  it('should allow a user to log in with valid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('user@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[class="btn btn-default"]').click();
    cy.url().should('eq', 'https://automationexercise.com/');
  });

  it('should display an error when login fails', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('invalid@example.com');
    cy.get('input[name="password"]').type('wrongpassword');
    cy.get('button[class="btn btn-default"]').click();
    // Assuming an error message appears, we can't assert on its content, but we can check for visibility of the login form.
    cy.get('section[id="form"]').should('be.visible');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should allow a user to log in with valid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'user@example.com');
    await page.fill('input[name="password"]', 'password123');
    await page.click('button[class="btn btn-default"]');
    await page.waitForURL('https://automationexercise.com/');
  });

  test('should display an error when login fails', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'invalid@example.com');
    await page.fill('input[name="password"]', 'wrongpassword');
    await page.click('button[class="btn btn-default"]');
    // Assuming an error message appears, we can't assert on its content, but we can check for visibility of the login form.
    await page.waitForSelector('section[id="form"]');
  });
});
